create table igpt_demo_employees (
    employee_id   number generated by default on null as identity (start with 101) primary key,
    full_name     varchar2(100) not null,
    email         varchar2(200) not null,
    department    varchar2(10)  not null,
    job_title     varchar2(100) not null,
    manager_id    number references igpt_demo_employees,
    hire_date     date          not null,
    salary        number(12,2)  not null,
    bonus         number(12,2),
    weekly_hours  number(4,1)   default 40 not null,
    is_remote     varchar2(1)   default 'N' not null check (is_remote in ('Y','N')),
    constraint igpt_demo_emp_dept_ck check (department in ('ENG','SAL','MKT','FIN','HR','OPS'))
);
